    int sum = 0;
    for (int i = 0; key[i]; i++) sum += key[i];
    return sum % TABLE_SIZE;
}

void insert(char* key, int value) {
    int idx = hashFunction(key);
    strcpy(hashTable[idx].key, key);
    hashTable[idx].value = value;
    hashTable[idx].occupied = 1;
}

