#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define SIZE 100

typedef struct Node {
    char key[50];
    int value;
    struct Node* next;
} Node;

Node* table[SIZE];

int hash(char* key) {
    int h = 0;
    for (int i = 0; key[i]; i++) h = (h * 31 + key[i]) % SIZE;
    return h;
}

void insert(char* key, int val) {
    int idx = hash(key);
    Node* node = malloc(sizeof(Node));
    strcpy(node->key, key);
    node->value = val;
    node->next = table[idx];
    table[idx] = node;
}

int search(char* key) {
    int idx = hash(key);
    Node* cur = table[idx];
    while (cur) {
        if (strcmp(cur->key, key) == 0) return cur->value;
        cur = cur->next;
    }
    return -1;
}

int main() {
    memset(table, 0, sizeof(table));
    insert("Alice", 90);
    insert("Bob", 85);
    printf("Bob ka score: %d\n", search("Bob"));
    return 0;
}

