#include <iostream>
#include <list>
using namespace std;

// Chaining using Linked List
class HashTable {
    int size;
    list<pair<int,int>>* table;
public:
    HashTable(int s) : size(s) {
        table = new list<pair<int,int>>[size];
    }

    int hashFunc(int key) { return key % size; }

    void insert(int key, int value) {
        int idx = hashFunc(key);
        // Check if key already exists
        for (auto& p : table[idx]) {
            if (p.first == key) { p.second = value; return; }
        }
        table[idx].push_back({key, value});
    }

    int search(int key) {
        int idx = hashFunc(key);
        for (auto& p : table[idx]) {
            if (p.first == key) return p.second;
        }
        return -1;  // Not found
    }

    void display() {
        for (int i = 0; i < size; i++) {
            cout << "Index " << i << ": ";
            for (auto& p : table[i])
                cout << "(" << p.first << "," << p.second << ") ";
            cout << endl;
        }
    }
};

int main() {
    HashTable ht(7);
    ht.insert(10, 100);  // 10 % 7 = 3
    ht.insert(17, 200);  // 17 % 7 = 3 -> collision with 10!
    ht.insert(3, 300);   // 3 % 7 = 3  -> another collision!
    ht.display();
    cout << "Search 17: " << ht.search(17) << endl;  // 200
    return 0;
}

