    static LinkedList<int[]>[] table = new LinkedList[SIZE];

    static int hash(int key) { return key % SIZE; }

    static void insert(int key, int value) {
        int idx = hash(key);
        if (table[idx] == null) table[idx] = new LinkedList<>();
        for (int[] pair : table[idx]) {
            if (pair[0] == key) { pair[1] = value; return; }
        }
        table[idx].add(new int[]{key, value});
    }

    static int search(int key) {
        int idx = hash(key);
        if (table[idx] == null) return -1;
        for (int[] pair : table[idx]) {
            if (pair[0] == key) return pair[1];
        }
        return -1;
    }

    public static void main(String[] args) {
        insert(10, 100);  // 10 % 7 = 3
        insert(17, 200);  // 17 % 7 = 3 -> collision!
        insert(3, 300);   // 3 % 7 = 3 -> collision!
