#include <iostream>
#include <unordered_map>
#include <vector>
#include <string>
using namespace std;

// Frequency Count
void countFrequency(vector<int>& arr) {
    unordered_map<int, int> freq;
    for (int x : arr) freq[x]++;

    for (auto& [val, count] : freq) {
        cout << val << " appears " << count << " times" << endl;
    }
}

// Find Duplicates
vector<int> findDuplicates(vector<int>& arr) {
    unordered_map<int, int> freq;
    vector<int> duplicates;
    for (int x : arr) {
        freq[x]++;
        if (freq[x] == 2) duplicates.push_back(x);
    }
    return duplicates;
}

// Anagram Check
bool isAnagram(string s, string t) {
    if (s.length() != t.length()) return false;
    unordered_map<char, int> freq;
    for (char c : s) freq[c]++;
    for (char c : t) {
        freq[c]--;
        if (freq[c] < 0) return false;
    }
    return true;
}

int main() {
    vector<int> arr = {1, 3, 2, 1, 4, 3, 1};
    countFrequency(arr);

    auto dups = findDuplicates(arr);
    cout << "Duplicates: ";
    for (int x : dups) cout << x << " ";
    cout << endl;

    cout << "listen & silent anagram? " 
         << (isAnagram("listen", "silent") ? "Yes" : "No") << endl;
    return 0;
}

