import java.util.*;

public class Main {
    // Frequency Count
    static void countFrequency(int[] arr) {
        HashMap<Integer, Integer> freq = new HashMap<>();
        for (int x : arr) freq.merge(x, 1, Integer::sum);
        freq.forEach((val, count) ->
            System.out.println(val + " appears " + count + " times"));
    }

    // Find Duplicates
    static List<Integer> findDuplicates(int[] arr) {
        HashMap<Integer, Integer> freq = new HashMap<>();
        List<Integer> dups = new ArrayList<>();
        for (int x : arr) {
            freq.merge(x, 1, Integer::sum);
            if (freq.get(x) == 2) dups.add(x);
        }
        return dups;
    }

    // Anagram Check
    static boolean isAnagram(String s, String t) {
        if (s.length() != t.length()) return false;
        int[] freq = new int[26];
        for (char c : s.toCharArray()) freq[c - 'a']++;
        for (char c : t.toCharArray()) freq[c - 'a']--;
        for (int f : freq) if (f != 0) return false;
        return true;
    }

    public static void main(String[] args) {
        int[] arr = {1, 3, 2, 1, 4, 3, 1};
        countFrequency(arr);
        System.out.println("Duplicates: " + findDuplicates(arr));
        System.out.println("Anagram? " + isAnagram("listen", "silent"));
    }
