#include <string.h>

// Simple frequency count for small values
void countFrequency(int arr[], int n) {
    int freq[1001] = {0};
    for (int i = 0; i < n; i++) freq[arr[i]]++;
    for (int i = 0; i <= 1000; i++) {
        if (freq[i] > 0)
            printf("%d appears %d times\n", i, freq[i]);
    }
}

// Anagram Check
int isAnagram(char* s, char* t) {
    if (strlen(s) != strlen(t)) return 0;
    int freq[26] = {0};
    for (int i = 0; s[i]; i++) freq[s[i] - 'a']++;
    for (int i = 0; t[i]; i++) freq[t[i] - 'a']--;
    for (int i = 0; i < 26; i++) if (freq[i] != 0) return 0;
    return 1;
}

int main() {
    int arr[] = {1, 3, 2, 1, 4, 3, 1};
    countFrequency(arr, 7);
    printf("Anagram? %s\n", isAnagram("listen", "silent") ? "Yes" : "No");
